import{_ as t,o as i,c as n,a2 as s}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Werte und Zusammenspiel mit anderen Adaptern","description":"","frontmatter":{"order":2,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/05.hintergrund/02.werte-und-integrationen.md"},"headers":[],"relativePath":"de/adapter/wled/hintergrund/werte-und-integrationen.md","filePath":"de/adapter/wled/hintergrund/werte-und-integrationen.md","lastUpdated":null}'),r={name:"de/adapter/wled/hintergrund/werte-und-integrationen.md"};function a(d,e,l,o,h,p){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="werte-und-zusammenspiel-mit-anderen-adaptern" tabindex="-1">Werte und Zusammenspiel mit anderen Adaptern <a class="header-anchor" href="#werte-und-zusammenspiel-mit-anderen-adaptern" aria-label="Permalink to &quot;Werte und Zusammenspiel mit anderen Adaptern&quot;">​</a></h1><p><a id="states-only-written-they-change"></a></p><h2 id="werden-states-nur-bei-anderung-geschrieben" tabindex="-1">Werden States nur bei Änderung geschrieben? <a class="header-anchor" href="#werden-states-nur-bei-anderung-geschrieben" aria-label="Permalink to &quot;Werden States nur bei Änderung geschrieben?&quot;">​</a></h2><p><strong>Kurz:</strong> Ja. Der Adapter schreibt Werte vom Gerät nur, wenn sich der Wert oder die Bestätigung (<code>ack</code>) geändert hat. Fragt er das Gerät ab und alles ist gleich geblieben, wird kein Datenpunkt geschrieben, und kein Skript wird ausgelöst.</p><p>Seit 2020 nutzt der Adapter dafür <code>setStateChanged</code> von ioBroker. Davor hat er bei jeder Abfrage alle Datenpunkte neu geschrieben (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/13" target="_blank" rel="noreferrer">#13</a>).</p><h3 id="was-das-fur-skripte-bedeutet" tabindex="-1">Was das für Skripte bedeutet <a class="header-anchor" href="#was-das-fur-skripte-bedeutet" aria-label="Permalink to &quot;Was das für Skripte bedeutet&quot;">​</a></h3><ul><li><strong>Ein Auslöser mit <code>change: &#39;ne&#39;</code></strong> reagiert nur, wenn sich der Wert wirklich ändert. Das ist für die meisten Skripte richtig.</li><li><strong>Ein Auslöser mit <code>change: &#39;any&#39;</code></strong> reagiert auch, wenn nur die Bestätigung dazukommt. Schreibst du <code>on</code> auf <code>true</code>, kommen zwei Ereignisse an: dein Befehl mit <code>ack=false</code> und danach die Rückmeldung mit <code>ack=true</code> und demselben Wert.</li><li><strong>Mit <code>ack: true</code> im Auslöser</strong> reagiert dein Skript nur auf Rückmeldungen vom Gerät, mit <code>ack: false</code> nur auf Befehle, zum Beispiel aus VIS.</li></ul><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Reagiert nur, wenn das Gerät meldet, dass es eingeschaltet wurde (egal von wo)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.on&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, val: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, change: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ne&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ack: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;WLED ist an&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Der Zeitstempel eines Datenpunkts (<code>ts</code>) zeigt darum nicht, wann der Adapter das Gerät zuletzt erreicht hat, sondern wann der Wert zuletzt geschrieben wurde. Ein Licht, das stundenlang gleich leuchtet, hat einen alten Zeitstempel, obwohl alles funktioniert. Ob ein Gerät erreichbar ist, zeigt dir <code>_info._online</code>.</p></div><h3 id="weitere-regeln" tabindex="-1">Weitere Regeln <a class="header-anchor" href="#weitere-regeln" aria-label="Permalink to &quot;Weitere Regeln&quot;">​</a></h3><ul><li>Werte, die das Gerät leer (<code>null</code>) meldet, schreibt der Adapter nicht. Der Datenpunkt behält seinen alten Wert.</li><li>Ist ein Gerät nicht erreichbar, behalten die Datenpunkte ihren letzten Wert. Nur <code>on</code>, <code>bri</code> und <code>_online</code> setzt der Adapter in bestimmten Fällen zurück.</li><li>Datenpunkte, die WLED nie zurückmeldet (<code>tt</code>, <code>psave</code>, <code>action</code>, <code>rawCommand</code>, <code>udpn.nn</code>), zeigen nur, was zuletzt geschrieben wurde.</li></ul><p><strong>Siehe auch:</strong></p><ul><li><a href="./verbindung-und-aktualisierung#become-false-device-goes-offline">Warum wird on false, wenn das Gerät offline geht, und was passiert beim Adapterstart?</a></li><li><a href="./verbindung-und-aktualisierung#tell-whether-device-really-online">Woran sehe ich, ob ein Gerät wirklich online ist (info.connection, _online)?</a></li><li><a href="./verbindung-und-aktualisierung#states-only-updated-after-30">Warum werden Zustände erst nach 30 Sekunden aktualisiert, gibt es Push statt Polling?</a></li><li><a href="./../anleitungen/skripte#tell-whether-wled-was-switched">Woran erkenne ich, ob WLED per Telegram, VIS oder Web-Oberfläche geschaltet wurde?</a></li></ul><p><a id="need-mqtt-adapter-wled-presets"></a></p><h2 id="brauche-ich-den-mqtt-adapter-fur-wled-presets" tabindex="-1">Brauche ich den MQTT-Adapter für WLED-Presets? <a class="header-anchor" href="#brauche-ich-den-mqtt-adapter-fur-wled-presets" aria-label="Permalink to &quot;Brauche ich den MQTT-Adapter für WLED-Presets?&quot;">​</a></h2><p><strong>Kurz:</strong> Nein. Der WLED-Adapter spricht direkt mit dem Gerät, über die JSON-API per HTTP und über eine WebSocket-Verbindung. Einen MQTT-Adapter oder MQTT-Broker brauchst du dafür nicht. Alle Datenpunkte, auch <code>ps</code> für Presets, legt der Adapter selbst an.</p><p>So arbeitet der Adapter:</p><ul><li><strong>Abfragen:</strong> Er liest den Zustand des Geräts per HTTP von <code>http://192.168.x.y/json</code>.</li><li><strong>Live-Änderungen:</strong> Er hält eine WebSocket-Verbindung zu <code>ws://192.168.x.y/ws</code>. Darüber meldet WLED Änderungen sofort, auch wenn du in der WLED-App schaltest.</li><li><strong>Befehle:</strong> Er schickt sie über die WebSocket-Verbindung, und wenn die nicht steht, per HTTP an <code>http://192.168.x.y/json</code>.</li><li><strong>Geräte finden:</strong> Er sucht sie per Bonjour (mDNS) im Netz.</li></ul><p>Der Adapter enthält keinen MQTT-Teil. Unter seinen Abhängigkeiten ist keine MQTT-Bibliothek.</p><h3 id="presets-ohne-mqtt-schalten" tabindex="-1">Presets ohne MQTT schalten <a class="header-anchor" href="#presets-ohne-mqtt-schalten" aria-label="Permalink to &quot;Presets ohne MQTT schalten&quot;">​</a></h3><p>Schreib die Nummer des Presets als Steuerbefehl in <code>wled.0.&lt;Gerät&gt;.ps</code>, zum Beispiel <code>setState(&#39;wled.0.&lt;Gerät&gt;.ps&#39;, 3);</code>. Wie das im Einzelnen geht, steht unter <a href="./../anleitungen/effekte-und-presets#switch-wled-presets-via-ps">Wie schalte ich WLED-Presets per Datenpunkt (ps) in VIS, Blockly oder Skript?</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>WLED kann selbst MQTT sprechen. Das ist eine eigene Schnittstelle der Firmware und hat mit dem WLED-Adapter nichts zu tun. Nutzt du sie zusätzlich, zum Beispiel mit dem MQTT-Adapter, steuerst du dasselbe Gerät über zwei Wege mit getrennten Datenpunkten. Für den WLED-Adapter ist das nicht nötig.</p></div><p><strong>Siehe auch:</strong></p><ul><li><a href="./../erste-schritte/installation#wled-firmware-requirements-adapter-need">Welche WLED-Firmware und welche Voraussetzungen braucht der Adapter?</a></li><li><a href="./verbindung-und-aktualisierung#states-only-updated-after-30">Warum werden Zustände erst nach 30 Sekunden aktualisiert, gibt es Push statt Polling?</a></li></ul><p><a id="usermod-buttons-gpio-states"></a></p><h2 id="wie-bekomme-ich-usermod-werte-taster-kontakte-oder-gpio-pins-als-datenpunkt" tabindex="-1">Wie bekomme ich Usermod-Werte, Taster, Kontakte oder GPIO-Pins als Datenpunkt? <a class="header-anchor" href="#wie-bekomme-ich-usermod-werte-taster-kontakte-oder-gpio-pins-als-datenpunkt" aria-label="Permalink to &quot;Wie bekomme ich Usermod-Werte, Taster, Kontakte oder GPIO-Pins als Datenpunkt?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter zeigt nur, was WLED über seine JSON-API meldet, und dort gibt es keine Werte für Taster, Kontakte oder GPIO-Pins. Werte, die ein Usermod auf der Info-Seite von WLED anzeigt, erscheinen ab v0.10.0 als eigene Datenpunkte unter <code>_info.u</code>. Einen Taster ohne Usermod erkennst du über einen Preset, den WLED beim Drücken lädt, und den Datenpunkt <code>ps</code>.</p><h3 id="usermod-werte-unter-info-u" tabindex="-1">Usermod-Werte unter <code>_info.u</code> <a class="header-anchor" href="#usermod-werte-unter-info-u" aria-label="Permalink to &quot;Usermod-Werte unter \`_info.u\`&quot;">​</a></h3><p>Usermods sind Erweiterungen der WLED-Firmware, zum Beispiel für einen Temperatursensor. Viele zeigen ihre Werte auf der Info-Seite von WLED an. Diese Werte meldet WLED in der JSON-API unter <code>info.u</code>.</p><p><strong>Ab v0.10.0:</strong> Der Adapter legt für jeden dieser Werte einen Datenpunkt <code>wled.0.&lt;Gerät&gt;._info.u.&lt;Name&gt;</code> an (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/929" target="_blank" rel="noreferrer">#929</a>):</p><ul><li>Der Name kommt aus WLED, ohne HTML. In der ID bleiben nur Buchstaben, Ziffern, <code>_</code> und <code>-</code>, zum Beispiel wird „Temperature“ zu <code>_info.u.Temperature</code>.</li><li>Der Wert ist eine Zahl, ein Wahrheitswert oder Text, je nachdem, was der Usermod meldet. Eine Einheit wie „°C“ steht im Objekt.</li><li>Die Datenpunkte sind nur lesbar.</li><li>Der Adapter liest sie bei jeder Abfrage neu, also im Abfrageintervall der Instanz (Standard 30 Sekunden). Über die WebSocket-Verbindung meldet WLED sie nicht.</li><li>Fällt ein Wert in WLED weg, entfernt der Adapter den Datenpunkt beim nächsten Verbindungsaufbau.</li></ul><p>Meldet ein Usermod den Zustand eines Tasters, eines Reed-Kontakts oder eines GPIO-Pins auf der Info-Seite, bekommst du ihn auf demselben Weg (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/928" target="_blank" rel="noreferrer">#928</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/931" target="_blank" rel="noreferrer">#931</a>). Ob es einen solchen Usermod für deinen Aufbau gibt, hängt von deiner Firmware ab. Die Standard-Firmware von WLED hat keinen.</p><p><strong>Bis v0.9.3:</strong> Usermod-Werte erscheinen auch schon unter <code>_info.u</code>, aber mit dem rohen Namen aus WLED als ID und mit Wert und Einheit zusammen als Text, zum Beispiel <code>[21.5,&quot;°C&quot;]</code>. Enthält der Name HTML, wird die ID unleserlich.</p><h3 id="taster-oder-kontakt-ohne-usermod-uber-einen-preset" tabindex="-1">Taster oder Kontakt ohne Usermod: über einen Preset <a class="header-anchor" href="#taster-oder-kontakt-ohne-usermod-uber-einen-preset" aria-label="Permalink to &quot;Taster oder Kontakt ohne Usermod: über einen Preset&quot;">​</a></h3><p>WLED kann einem Taster, einem Schalter oder einem Bewegungsmelder an einem GPIO-Pin Presets zuweisen. Lädt WLED dabei einen Preset, siehst du das in ioBroker an <code>ps</code>.</p><ol><li><p>Richte in WLED unter „Config“ › „LED Preferences“ den Taster mit seinem GPIO-Pin ein. Für einen Reed-Kontakt wählst du als Typ „Switch“.</p></li><li><p>Leg für jede Aktion einen eigenen Preset an, zum Beispiel Preset <code>20</code> für „kurz gedrückt“ oder für einen Kontakt Preset <code>21</code> für „offen“ und <code>22</code> für „zu“.</p></li><li><p>Weise die Presets unter „Config“ › „Time &amp; Macros“ im Bereich „Button Action Presets“ den Aktionen zu.</p></li><li><p>Reagiere in ioBroker auf <code>ps</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0.&lt;Gerät&gt;.ps&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, change: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ne&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ack: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">obj</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (obj.state.val </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 21</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Kontakt offen&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (obj.state.val </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Kontakt zu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div></li></ol><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Drückst du denselben Taster zweimal hintereinander, lädt WLED denselben Preset noch einmal. <code>ps</code> ändert sich dann nicht, und dein Skript bemerkt den zweiten Druck nicht. Für einen Kontakt mit zwei Zuständen (offen, zu) und zwei Presets ist das kein Problem, weil sich <code>ps</code> bei jedem Wechsel ändert.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Soll der Preset das Licht nicht verändern, legst du ihn in WLED als Preset mit API-Befehl an (Makro). WLED speichert dann keine Farben und keinen Effekt, sondern führt nur den Befehl aus.</p></div><p><strong>Siehe auch:</strong></p><ul><li><a href="./../anleitungen/effekte-und-presets#switch-wled-presets-via-ps">Wie schalte ich WLED-Presets per Datenpunkt (ps) in VIS, Blockly oder Skript?</a></li><li><a href="./../anleitungen/skripte#tell-whether-wled-was-switched">Woran erkenne ich, ob WLED per Telegram, VIS oder Web-Oberfläche geschaltet wurde?</a></li><li><a href="#states-only-written-they-change">Werden States nur bei Änderung geschrieben?</a></li><li><a href="./../referenz/datenpunkte#individual-wled-states-mean">Was bedeuten die einzelnen WLED-Datenpunkte?</a></li></ul>`,40)])])}const k=t(r,[["render",a]]);export{c as __pageData,k as default};
